import{_ as e,c as s,o as r,ae as o}from"./chunks/framework.CHDT0Kbg.js";const h=JSON.parse('{"title":"Opciones de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-choices.md","filePath":"es/guide/privacy-choices.md","lastUpdated":1795170900000}'),i={name:"es/guide/privacy-choices.md"};function d(t,a,n,c,l,u){return r(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to &quot;Opciones de privacidad&quot;">​</a></h1><p>Formas sencillas de mantener el control.</p><h2 id="navegar-sin-dejar-rastro" tabindex="-1">Navegar sin dejar rastro <a class="header-anchor" href="#navegar-sin-dejar-rastro" aria-label="Permalink to &quot;Navegar sin dejar rastro&quot;">​</a></h2><p>Usa una ventana privada (⌘⇧N). No escribe en el historial ni recuerda la sesión, y sus pestañas desaparecen al cerrarla.</p><h2 id="borrar-lo-guardado" tabindex="-1">Borrar lo guardado <a class="header-anchor" href="#borrar-lo-guardado" aria-label="Permalink to &quot;Borrar lo guardado&quot;">​</a></h2><p>Elimina las cookies y los datos de sitios desde el gestor de cookies de los ajustes. El historial y las descargas también se pueden borrar allí.</p><h2 id="decide-que-puede-hacer-cada-sitio" tabindex="-1">Decide qué puede hacer cada sitio <a class="header-anchor" href="#decide-que-puede-hacer-cada-sitio" aria-label="Permalink to &quot;Decide qué puede hacer cada sitio&quot;">​</a></h2><p>La cámara, el micrófono y el acceso a archivos se recuerdan por sitio. Permite los que confías y rechaza los demás en los ajustes. Las ventanas emergentes solo se abren en los sitios que autorices.</p><h2 id="controla-las-funciones-en-segundo-plano" tabindex="-1">Controla las funciones en segundo plano <a class="header-anchor" href="#controla-las-funciones-en-segundo-plano" aria-label="Permalink to &quot;Controla las funciones en segundo plano&quot;">​</a></h2><p>Activa o desactiva las suscripciones de bloqueo cuando quieras desde los ajustes. Si una está desactivada, no se descarga ninguna lista.</p><h2 id="elige-tu-motor-de-busqueda" tabindex="-1">Elige tu motor de búsqueda <a class="header-anchor" href="#elige-tu-motor-de-busqueda" aria-label="Permalink to &quot;Elige tu motor de búsqueda&quot;">​</a></h2><p>Establece tu motor predeterminado en los ajustes. Las sugerencias provienen del motor que elijas.</p><h2 id="¿dudas" tabindex="-1">¿Dudas? <a class="header-anchor" href="#¿dudas" aria-label="Permalink to &quot;¿Dudas?&quot;">​</a></h2><p>Escribe a <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> si quieres saber más sobre cómo se tratan tus datos.</p>',14)])])}const m=e(i,[["render",d]]);export{h as __pageData,m as default};
